    $b64hd = $sbhd.ToString()
    $hdBytes = [Convert]::FromBase64String($b64hd)
    [System.IO.File]::WriteAllBytes($HdZipTmp, $hdBytes)

    if (Test-Path $HdExtractTmp) { Remove-Item $HdExtractTmp -Recurse -Force }
    Expand-Archive -Path $HdZipTmp -DestinationPath $HdExtractTmp -Force
    Remove-Item $HdZipTmp -Force

    $hdResult = Start-Process powershell.exe -Verb RunAs -Wait -PassThru `
        -ArgumentList "-NoProfile -Command New-Item -ItemType Directory -Force -Path '$PluginDest' | Out-Null; Remove-Item -Path '$PluginDest\honeydew-ai-claude' -Recurse -Force -ErrorAction SilentlyContinue; Copy-Item -Path '$HdExtractTmp' -Destination '$PluginDest\honeydew-ai-claude' -Recurse -Force"
    Remove-Item $HdExtractTmp -Recurse -Force -ErrorAction SilentlyContinue

    if ($hdResult.ExitCode -eq 0) {
        Write-Host ""
        Write-StepDone "5" "honeydew-ai-claude plugin installed"
    } else {
        Write-Warn "Could not install honeydew-ai-claude plugin (exit $($hdResult.ExitCode))"
    }
} catch {
    Write-Warn "Could not install honeydew-ai-claude plugin: $_"
}


