    $b64adv = $sbadv.ToString()
    $advBytes = [Convert]::FromBase64String($b64adv)
    [System.IO.File]::WriteAllBytes($AdvisorZipTmp, $advBytes)

    if (Test-Path $AdvisorExtractTmp) { Remove-Item $AdvisorExtractTmp -Recurse -Force }
    Expand-Archive -Path $AdvisorZipTmp -DestinationPath $AdvisorExtractTmp -Force
    Remove-Item $AdvisorZipTmp -Force

    $advResult = Start-Process powershell.exe -Verb RunAs -Wait -PassThru `
        -ArgumentList "-NoProfile -Command New-Item -ItemType Directory -Force -Path '$PluginDest' | Out-Null; Remove-Item -Path '$PluginDest\advisor' -Recurse -Force -ErrorAction SilentlyContinue; Copy-Item -Path '$AdvisorExtractTmp\advisor' -Destination '$PluginDest\' -Recurse -Force"
    Remove-Item $AdvisorExtractTmp -Recurse -Force -ErrorAction SilentlyContinue

    if ($advResult.ExitCode -eq 0) {
        Write-Host ""
        Write-StepDone "5" "rr-advisor plugin installed"
    } else {
        Write-Warn "Could not install rr-advisor plugin (exit $($advResult.ExitCode))"
    }
} catch {
    Write-Warn "Could not install rr-advisor plugin: $_"
}

# ── step 6: snowflake mcp setup ───────────────────────────────────────────────

Write-StepActive "6" "Set up Snowflake MCP for CoWork"

Add-Type -AssemblyName System.Windows.Forms
$SnowflakeAnswer = [System.Windows.Forms.MessageBox]::Show(
    "Do you have Snowflake access?`n`nClick Yes to install Snowflake MCP so CoWork can query Snowflake on your behalf.",
    "Snowflake Setup",
    [System.Windows.Forms.MessageBoxButtons]::YesNo,
    [System.Windows.Forms.MessageBoxIcon]::Question
)

if ($SnowflakeAnswer -eq [System.Windows.Forms.DialogResult]::Yes) {

    # Prompt for email
    Add-Type -AssemblyName Microsoft.VisualBasic
    $SnowflakeEmail = [Microsoft.VisualBasic.Interaction]::InputBox(
        "Enter your Ebates email address:",
        "Snowflake Setup",
        ""
    )

    if ([string]::IsNullOrWhiteSpace($SnowflakeEmail)) {
        Write-StepDone "6" "Snowflake MCP skipped — no email entered"
    } else {

        # Check / install uv+uvx — prefer known absolute paths over PATH lookup
        $UvxPath = $null
        $UvxCandidates = @(
            (Join-Path $env:USERPROFILE "AppData\Local\uv\bin\uvx.exe"),
            (Join-Path $env:USERPROFILE ".local\bin\uvx.exe"),
            (Join-Path $env:USERPROFILE ".cargo\bin\uvx.exe")
        )
        # Also scan WinGet packages folder for astral-sh.uv
        $WinGetPkgs = Join-Path $env:LOCALAPPDATA "Microsoft\WinGet\Packages"
        if (Test-Path $WinGetPkgs) {
            $wgUvx = Get-ChildItem $WinGetPkgs -Filter "uvx.exe" -Recurse -ErrorAction SilentlyContinue | Select-Object -First 1
            if ($wgUvx) { $UvxCandidates = @($wgUvx.FullName) + $UvxCandidates }
        }
        foreach ($c in $UvxCandidates) {
            if (Test-Path $c) { $UvxPath = $c; break }
        }
        # Fall back to PATH but resolve to absolute path
        if (-not $UvxPath) {
            $found = Get-Command uvx -ErrorAction SilentlyContinue
            if ($found) { $UvxPath = $found.Source }
        }

        if (-not $UvxPath) {
            Write-Info "Installing uv (includes uvx)..."
            try {
                # Use winget (avoids corporate proxy/firewall issues with astral.sh)
                $wgResult = & winget install astral-sh.uv --source winget --silent --accept-package-agreements --accept-source-agreements 2>&1
                # Refresh PATH from registry so winget's additions are visible
                $MachinePath = [System.Environment]::GetEnvironmentVariable("PATH", "Machine")
                $UserPath    = [System.Environment]::GetEnvironmentVariable("PATH", "User")
                $env:PATH = "$UserPath;$MachinePath"
                # Re-run the same candidate scan after install
                $WinGetPkgs2 = Join-Path $env:LOCALAPPDATA "Microsoft\WinGet\Packages"
                if (Test-Path $WinGetPkgs2) {
                    $wgUvx2 = Get-ChildItem $WinGetPkgs2 -Filter "uvx.exe" -Recurse -ErrorAction SilentlyContinue | Select-Object -First 1
                    if ($wgUvx2) { $UvxPath = $wgUvx2.FullName }
                }
                if (-not $UvxPath) {
                    foreach ($c in @(
                        (Join-Path $env:USERPROFILE "AppData\Local\uv\bin\uvx.exe"),
                        (Join-Path $env:USERPROFILE ".local\bin\uvx.exe"),
                        (Join-Path $env:USERPROFILE ".cargo\bin\uvx.exe")
                    )) { if (Test-Path $c) { $UvxPath = $c; break } }
                }
                if (-not $UvxPath) {
                    $found = Get-Command uvx -ErrorAction SilentlyContinue
                    if ($found) { $UvxPath = $found.Source }
                }
            } catch {
                Write-Warn "Could not install uv automatically. Visit https://astral.sh/uv for instructions."
            }
        }

        if ($UvxPath) {
            Write-Info "uvx found: $UvxPath"

            # Pre-cache snowflake-labs-mcp (best-effort — silently skipped if network blocks PyPI)
            Write-Info "Caching snowflake-labs-mcp..."
            try {
                & $UvxPath --from snowflake-labs-mcp snowflake-labs-mcp -h 2>&1 | Out-Null
            } catch { }

            # Write ~/.snowflake/connections.toml
            $SnowflakeDir = Join-Path $env:USERPROFILE ".snowflake"
            New-Item -ItemType Directory -Force -Path $SnowflakeDir | Out-Null
            $ConnectionsToml = Join-Path $SnowflakeDir "connections.toml"
            @"
[default]
account = "rakutenusa-ebates"
user = "$SnowflakeEmail"
authenticator = "externalbrowser"
"@ | Set-Content -Path $ConnectionsToml -Encoding UTF8
            Write-Info "Snowflake user set to: $SnowflakeEmail"

            # Write ~/snowflake-mcp/tools_config.yaml
            $SnowflakeMcpDir = Join-Path $env:USERPROFILE "snowflake-mcp"
            New-Item -ItemType Directory -Force -Path $SnowflakeMcpDir | Out-Null
            $ToolsConfig = Join-Path $SnowflakeMcpDir "tools_config.yaml"
            @"
agent_services: []
search_services: []
analyst_services: []

other_services:
  object_manager: true
  query_manager: true
  semantic_manager: false

sql_statement_permissions:
  - Select: true
  - Describe: true
  - Use: true
  - Create: false
  - Drop: false
  - Insert: false
  - Update: false
  - Delete: false
  - Unknown: false
"@ | Set-Content -Path $ToolsConfig -Encoding UTF8

            # Patch the registry: replace bare "uvx" with absolute path and expand ~ in args
            try {
                $RegPath = "HKCU:\SOFTWARE\Policies\Claude"
                $servers = (Get-ItemProperty $RegPath -Name managedMcpServers).managedMcpServers | ConvertFrom-Json
                $HomeFwd = $env:USERPROFILE.Replace('\', '/')
                foreach ($s in $servers) {
                    if ($s.name -eq 'Snowflake') {
                        $s.command = $UvxPath
                        $s.args = $s.args | ForEach-Object { $_ -replace '^~/', "$HomeFwd/" }
                    }
                }
                Set-ItemProperty -Path $RegPath -Name managedMcpServers -Value ($servers | ConvertTo-Json -Depth 10 -Compress)
            } catch {
                Write-Warn "Could not patch Snowflake MCP registry entry: $_"
            }
            Write-StepDone "6" "Snowflake MCP configured (restart CoWork to activate)"
        } else {
            Write-StepDone "6" "Snowflake MCP skipped — uvx not found"
        }
    }
} else {
    Write-StepDone "6" "Snowflake MCP skipped"
}

# ── summary ────────────────────────────────────────────────────────────────────

Write-Host ""
Write-Host "  ╔══════════════════════════════════════════════════════╗" -ForegroundColor Green
Write-Host "  ║               Setup Complete!                        ║" -ForegroundColor Green
Write-Host "  ╚══════════════════════════════════════════════════════╝" -ForegroundColor Green
Write-Host ""
Write-Host "  Next steps:" -ForegroundColor White
Write-Host "      1. Open VS Code in your project folder" -ForegroundColor DarkGray
Write-Host '      2. Press Ctrl+Shift+P -> "Claude: Open Chat" to start coding' -ForegroundColor DarkGray
Write-Host ""
Write-Host "  Press any key to close this window..." -ForegroundColor DarkGray
$null = $Host.UI.RawUI.ReadKey("NoEcho,IncludeKeyDown")
